create table public.new_collections(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 1 and 100),starts_on date not null,ends_on date not null,published boolean not null default false,created_at timestamptz not null default now(),check(ends_on>=starts_on and ends_on<=starts_on+31),unique(starts_on,ends_on));
create table public.new_items(id uuid primary key default gen_random_uuid(),collection_id uuid not null references public.new_collections(id) on delete cascade,name text not null check(length(name) between 1 and 180),detail text not null default '' check(length(detail)<=300),description text not null default '' check(length(description)<=800),image_path text not null check(length(image_path)>0),catalog_url text not null default '' check(catalog_url='' or catalog_url ~ '^https://chizhik[.]club/product/[a-zA-Z0-9_%-]+/$'),sort_order integer not null default 0 check(sort_order>=0),created_at timestamptz not null default now());
create index new_items_collection on public.new_items(collection_id,sort_order);
alter table public.new_collections enable row level security;
alter table public.new_items enable row level security;
grant select on public.new_collections,public.new_items to anon,authenticated;
grant insert,update,delete on public.new_collections,public.new_items to authenticated;
grant all on public.new_collections,public.new_items to service_role;
create policy public_new_collections on public.new_collections for select to anon using(published);
create policy signed_new_collections on public.new_collections for select to authenticated using(published or exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy public_new_items on public.new_items for select to anon using(exists(select 1 from public.new_collections p where p.id=collection_id and p.published));
create policy signed_new_items on public.new_items for select to authenticated using(exists(select 1 from public.new_collections p where p.id=collection_id and p.published) or exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy admin_new_collections_insert on public.new_collections for insert to authenticated with check(exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy admin_new_collections_update on public.new_collections for update to authenticated using(exists(select 1 from public.admins where user_id=(select auth.uid()))) with check(exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy admin_new_collections_delete on public.new_collections for delete to authenticated using(exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy admin_new_items_insert on public.new_items for insert to authenticated with check(exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy admin_new_items_update on public.new_items for update to authenticated using(exists(select 1 from public.admins where user_id=(select auth.uid()))) with check(exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy admin_new_items_delete on public.new_items for delete to authenticated using(exists(select 1 from public.admins where user_id=(select auth.uid())));
create policy service_new_collections on public.new_collections for all to service_role using(true) with check(true);
create policy service_new_items on public.new_items for all to service_role using(true) with check(true);
